<?php
require_once __DIR__ . '/../includes/layout.php'; $me = require_login(['admin']); $pdo = db(); $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { check_csrf(); $action=$_POST['action']??''; $id=(int)($_POST['id']??0);
    if ($action==='delete' && $id !== $me['id']) { $pdo->prepare('DELETE FROM users WHERE id=?')->execute([$id]); redirect('pages/users.php','User deleted.'); }
    $name=trim($_POST['full_name']??''); $email=filter_input(INPUT_POST,'email',FILTER_VALIDATE_EMAIL); $role=$_POST['role']??'';
    if (!in_array($role,['admin','teacher','student'],true)||strlen($name)<2||!$email) $error='Enter a name, valid email and role.';
    elseif ($action==='create') { try { $password=$_POST['password']??''; if(strlen($password)<6) throw new RuntimeException('Password must have at least 6 characters.'); $pdo->prepare('INSERT INTO users(full_name,email,password,role) VALUES(?,?,?,?)')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role]); redirect('pages/users.php','User added.'); } catch (PDOException $e) {$error='Email address already exists.';} catch(RuntimeException $e){$error=$e->getMessage();} }
    elseif ($action==='update') { try { $pdo->prepare('UPDATE users SET full_name=?,email=?,role=?,is_active=? WHERE id=?')->execute([$name,$email,$role,isset($_POST['is_active'])?1:0,$id]); redirect('pages/users.php','User updated.'); } catch(PDOException $e) {$error='Email address already exists.';} }
}
$edit=null; if(isset($_GET['edit'])) { $q=$pdo->prepare('SELECT * FROM users WHERE id=?'); $q->execute([(int)$_GET['edit']]); $edit=$q->fetch(); }
$users=$pdo->query('SELECT id,full_name,email,role,is_active,created_at FROM users ORDER BY role,full_name')->fetchAll(); page_start('Manage Users',$me); ?>
<div class="content-grid"><section class="panel"><div class="panel-heading"><div><h2>Accounts</h2><p>Create, edit or remove portal users.</p></div></div><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="form-group"><label>Full name</label><input name="full_name" required value="<?=e($edit['full_name']??'')?>"></div><div class="form-group"><label>Email</label><input name="email" type="email" required value="<?=e($edit['email']??'')?>"></div><div class="form-group"><label>Role</label><select name="role"><option value="admin" <?=($edit['role']??'')==='admin'?'selected':''?>>Admin</option><option value="teacher" <?=($edit['role']??'')==='teacher'?'selected':''?>>Teacher</option><option value="student" <?=($edit['role']??'student')==='student'?'selected':''?>>Student</option></select></div><?php if(!$edit):?><div class="form-group"><label>Password</label><input name="password" type="password" minlength="6" required></div><?php else:?><label class="check"><input name="is_active" type="checkbox" <?=$edit['is_active']?'checked':''?>> Active account</label><?php endif;?><button class="btn btn-primary"><?=$edit?'Save User':'Add User'?></button><?php if($edit):?><a class="btn btn-secondary" href="users.php">Cancel</a><?php endif;?></form></section><section class="panel"><div class="panel-heading"><div><h2>All users</h2><p><?=count($users)?> accounts</p></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=e($u['full_name'])?></strong><br><small><?=e($u['email'])?></small></td><td><?=e(ucfirst($u['role']))?></td><td><?= $u['is_active']?'Active':'Disabled'?></td><td><a class="table-btn" href="?edit=<?=$u['id']?>">Edit</a><?php if($u['id']!=$me['id']):?><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="table-btn" onclick="return confirm('Delete this user?')">Delete</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></div><?php page_end(); ?>
